node -e "
const { deliver } = require('/workspace/src/dispatcher.js');

(async () => {
  // 1) Retries a 502 then succeeds, sends X-Event-Id, backs off.
  let calls = [];
  const io1 = { post: async (path, event, opts) => {
    calls.push({ path, event, opts });
    if (calls.length < 3) return { status: 502 };
    return { status: 200 };
  }};
  const t0 = Date.now();
  const res = await deliver(io1, { id: 'evt-1' }, { baseDelayMs: 10 });
  const elapsed = Date.now() - t0;
  console.log('test1 res:', JSON.stringify(res), 'calls:', calls.length, 'elapsed>=20:', elapsed >= 20);
  console.log('  headers:', JSON.stringify(calls.map(c => c.opts.headers)));

  // 2) Non-retryable 400 -> no retry.
  let calls2 = 0;
  const io2 = { post: async () => { calls2++; return { status: 400 }; } };
  const res2 = await deliver(io2, { id: 'evt-2' });
  console.log('test2 calls:', calls2, 'res:', JSON.stringify(res2));

  // 3) Thrown network error is retried, then success.
  let calls3 = 0;
  const io3 = { post: async () => { calls3++; if (calls3 === 1) throw new Error('ECONNRESET'); return { status: 200 }; }};
  const res3 = await deliver(io3, { id: 'evt-3' }, { baseDelayMs: 5 });
  console.log('test3 calls:', calls3, 'res:', JSON.stringify(res3));

  // 4) Persistent 502 after maxAttempts -> returns last response.
  const io4 = { post: async () => ({ status: 502 }) };
  const res4 = await deliver(io4, { id: 'evt-4' }, { maxAttempts: 3, baseDelayMs: 1 });
  console.log('test4 res:', JSON.stringify(res4));

  // 5) Persistent thrown error after maxAttempts -> throws.
  const io5 = { post: async () => { throw new Error('boom'); } };
  try {
    await deliver(io5, { id: 'evt-5' }, { maxAttempts: 2, baseDelayMs: 1 });
    console.log('test5 FAILED: should have thrown');
  } catch (e) {
    console.log('test5 threw:', e.message);
  }

  // 6) No event id -> posts without header, still retries.
  let calls6 = 0, opts6 = null;
  const io6 = { post: async (p, e, o) => { calls6++; opts6 = o; if (calls6 === 1) return { status: 503 }; return { status: 204 }; }};
  const res6 = await deliver(io6, {}, { baseDelayMs: 2 });
  console.log('test6 calls:', calls6, 'opts:', JSON.stringify(opts6), 'res:', JSON.stringify(res6));
})();
"

